// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

import {SmartLicense} from "./SmartLicense.sol";
import {Test} from "forge-std/Test.sol";

contract SmartLicenseTest is Test {
  SmartLicense lic;
  address licensor = makeAddr("smartphoneLicensor");
  address torch = makeAddr("torchOwner");
  address oracle = makeAddr("oracle");
  uint256 constant RATE = 1e12;            // 1 "centesimo" = 10^12 wei

  function setUp() public {
    // il contratto di test fa da produttore (licensee) e deposita 1 ether
    lic = new SmartLicense{value: 1 ether}(licensor, torch, oracle, RATE, 10);
  }

  function test_OnlyOracleReports() public {
    vm.expectRevert(bytes("only oracle"));
    lic.reportUsage(5);
  }

  function test_EventOnReport() public {
    vm.expectEmit(address(lic));
    emit SmartLicense.UsageReported(300, 300 * RATE);
    vm.prank(oracle);
    lic.reportUsage(300);
  }

  /**
   * hardhat-config: fuzz.runs = 500
   */
  function testFuzz_SplitIsExact(uint32 secs) public {
    vm.prank(oracle);
    lic.reportUsage(secs);
    uint256 due = uint256(secs) * RATE;
    uint256 paid = due < 1 ether ? due : 1 ether;   // si paga al massimo il deposito
    lic.settle();
    // la quota a monte è il 10% (arrotondato per difetto), il resto al licensor
    assertEq(torch.balance, paid * 10 / 100);
    assertEq(licensor.balance + torch.balance, paid);
    assertEq(lic.owed(), due - paid);
  }
}

