const info = JSON.parse(readFileSync("deployment.json", "utf8"));
const { viem } = await network.create();
const publicClient = await viem.getPublicClient();
const lic = await viem.getContractAt("SmartLicense", getAddress(info.address));

const reports = await publicClient.getContractEvents({
  address: lic.address, abi: lic.abi, eventName: "UsageReported", fromBlock: 0n,
});
const payments = await publicClient.getContractEvents({
  address: lic.address, abi: lic.abi, eventName: "RoyaltiesPaid", fromBlock: 0n,
});

let seconds = 0n;
for (const e of reports) seconds += e.args.usageSeconds!;
let toLicensor = 0n, toTorch = 0n;
for (const e of payments) { toLicensor += e.args.toLicensor!; toTorch += e.args.toUpstream!; }

const bal = (a: string) => publicClient.getBalance({ address: getAddress(a) });
console.log("blocco corrente      :", await publicClient.getBlockNumber());
console.log("report di uso        :", reports.length, "per", seconds, "secondi di torcia");
console.log("pagamenti (settle)   :", payments.length);
console.log("royalty al licensor  :", formatEther(toLicensor), "ETH");
console.log("royalty alla torcia  :", formatEther(toTorch), "ETH");
console.log("ancora dovuto (owed) :", formatEther(await lic.read.owed()), "ETH");
console.log("deposito residuo     :", formatEther(await bal(lic.address)), "ETH");
console.log("saldo torchOwner     :", formatEther(await bal(info.torchOwner)), "ETH");
